from pathlib import Path
from urllib.parse import urlparse,unquote
import json,os
root=Path(__file__).resolve().parent.parent;out=root/'output/library-shape-survey-v2'
recipes=json.loads((root/'Sources/PosterCore/Resources/ShapeLibrary/SurveyRecipes.json').read_text());refs=json.loads((root/'output/library-shape-survey-v1/manifest.json').read_text());lookup={r['id']:r for r in refs}
def relative(path):return os.path.relpath(path,out)
def local(url):return Path(unquote(urlparse(url).path))
data=[]
for r in recipes:
 ref=lookup[r['references'][0]['posterID']]
 data.append(dict(kind='default',recipe=r['id'],name=r['name'],mode='reference default',round=-1,rank=0,image='embeddings/'+r['id']+'.png',genome='embeddings/'+r['id']+'-scene.json',preset='embeddings/'+r['id']+'-preset.json',pdf='embeddings/'+r['id']+'.pdf',logic=r['logic'],reference=relative(ref['image']),tags=r['tags'],variantImages=['embeddings/'+r['id']+'.png']+[f'specimens/{r["id"]}/v{i}/poster.png' for i in range(4)]))
refinement=out/'echo-refinement/manifest.json'
for study in ['generations','echo-refinement']:
 for p in sorted((out/study).glob('survey-*/round-*/round.json')):
  d=json.loads(p.read_text());r=next(r for r in recipes if r['id']==d['recipeID'])
  final=int(d['round'])==7
  for c in d['candidates']:
   rank=next(i+1 for i,j in enumerate(d['judging']['results']) if j['id']==c['id'])
   item=dict(kind='generation',recipe=r['id'],name=r['name'],mode=c['mode'],round=d['round'],rank=rank,winner=rank==1,final=final and rank==1 and not (study=='generations' and r['id']=='survey-chevron-stack' and refinement.exists()),study=study,image=relative(local(c['imageURL'])),genome=relative(local(c['genomeURL'])),preset=relative(local(c['presetURL'])),record=relative(p),changed=c.get('changedPixelFraction'),tags=r['tags'],logic=f'{study} · round {d["round"]+1} · rank {rank} within this batch. '+('Final-round winner.' if final and rank==1 else ''),reference=relative(lookup[r['references'][0]['posterID']]['image']))
   if final and rank==1:item['pdf']=relative(p.parent.parent/'winner.pdf')
   data.append(item)
contextFile=out/'context-winners.json'
if contextFile.exists():
 for selection in json.loads(contextFile.read_text())['selections']:
  c=selection['candidate'];r=next(r for r in recipes if r['id']==selection['recipeID'])
  data.append(dict(kind='context',recipe=r['id'],name=r['name'],mode=selection['mode'],round=-1,rank=1,image=relative(local(c['imageURL'])),genome=relative(local(c['genomeURL'])),preset=relative(local(c['presetURL'])),record=relative(selection['roundRecord']),logic='Selected within this recipe and context from '+str(selection['cohortSize'])+' distinct outputs. Across-round Borda excludes batch-local Diversity.',reference=relative(lookup[r['references'][0]['posterID']]['image']),tags=r['tags']))
encoded=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Source shapes · Generative studies</title><style>
:root{font:16px/1.5 system-ui,sans-serif;color:#252821;background:#e7e5dd;color-scheme:light}*{box-sizing:border-box}body{margin:0}header,main,footer{max-width:1480px;margin:auto;padding:32px}header{padding-top:60px}h1{font-size:clamp(36px,5vw,64px);line-height:1.05;letter-spacing:-.045em;max-width:900px;margin:16px 0 24px}h2{font-size:21px;letter-spacing:-.02em;margin:0 0 12px}.intro{font-size:19px;max-width:850px}.label{font-size:12px;text-transform:uppercase;letter-spacing:.08em}.tools{display:flex;flex-wrap:wrap;gap:18px;margin-bottom:26px;align-items:end}label{display:flex;flex-direction:column;gap:5px;font-size:13px}select,input{font:inherit;color:inherit;background:#f5f2ea;border:1px solid #a5a69d;border-radius:6px;padding:10px;max-width:100%}#search{width:260px}a{color:#245b45;text-underline-offset:3px}:focus-visible{outline:3px solid #276147;outline-offset:4px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}article{background:#f5f2ea;border:1px solid #d2d0c6;border-radius:9px;overflow:hidden}.figure{height:410px;display:grid;place-items:center;background:#dedbd3;padding:10px}.figure img{width:100%;height:100%;object-fit:contain}.body{padding:22px}.body p{font-size:14px}.body .label{font-size:11px;color:#5a6254}.links{display:flex;flex-wrap:wrap;gap:12px}.tags{color:#65695c}#count{font-size:14px;color:#59614f}details{font-size:14px}summary{cursor:pointer}footer{font-size:13px;color:#5a6254}#empty{padding:30px}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){header,main,footer{padding:22px}.grid{grid-template-columns:1fr}.figure{height:440px}}
</style><header><p class="label">Shape and type systems · Source-calibrated defaults</p><h1>Reference first.<br>Variations by choice.</h1><p class="intro">Fourteen procedural systems, including six new grammars. Defaults follow the chosen reference’s topology and proportions. Displacement, extra repetition, cropping and abstraction remain explicit variations.</p><p>The scalloped example is editable F U / B U typography, not a decorative frame. The wireframe stack has no displaced slices or gaps by default; those are optional extensions.</p><p>Generation testing uses actual library compositions and supplied images, eight rounds per system. Batch ranks are relative jury preferences. No taste votes or training labels are created.</p></header><main><div class="tools"><label>Show<select id="view"><option value="defaults">Reference defaults</option><option value="final">Final-round winners</option><option value="contexts">Winners by context</option><option value="round">All round winners</option><option value="all">All generated candidates</option></select></label><label>System<select id="recipe"><option value="">All 14 systems</option></select></label><label>Find a technique<input id="search" type="search" placeholder="Scalloped, wireframe, branching…"></label><span id="count" aria-live="polite"></span></div><div class="grid" id="grid"></div><p id="empty" hidden>No matching outputs.</p></main><footer><a href="canonical-defaults.json">Canonical defaults</a> · <a href="systems.json">Construction rules</a> · <a href="context-winners.json">Context ballots</a> · <a href="validation.json">Verification</a> · <a href="embeddings/survey-embeddings.json">Shape/type embeddings</a><p>Procedural interpretations of visible source evidence. The original designer’s exact construction is unknown. Source links open complete posters; source crops are not shown.</p></footer><script type="application/json" id="data">'''+encoded+'''</script><script>
const items=JSON.parse(document.getElementById('data').textContent);const grid=document.getElementById('grid'),view=document.getElementById('view'),recipe=document.getElementById('recipe'),search=document.getElementById('search'),count=document.getElementById('count');
for(const item of items.filter(x=>x.kind==='default')){const o=document.createElement('option');o.value=item.recipe;o.textContent=item.name;recipe.append(o);}
function element(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;}
function link(label,path){const a=element('a',label);a.href=path;return a;}
function render(){const q=search.value.trim().toLowerCase();const shown=items.filter(x=>{const mode=view.value;return (mode==='defaults'?x.kind==='default':mode==='final'?x.final:mode==='contexts'?x.kind==='context':mode==='round'?x.kind==='generation'&&x.winner:x.kind==='generation')&&(!recipe.value||x.recipe===recipe.value)&&(!q||(x.name+' '+x.tags.join(' ')).toLowerCase().includes(q));});grid.replaceChildren();count.textContent=shown.length+' outputs';document.getElementById('empty').hidden=shown.length>0;
for(const item of shown){const card=element('article'),figure=element('div',undefined,'figure'),img=element('img');img.src=item.image;img.alt=item.name+' · '+item.mode;img.loading='lazy';figure.append(img);const body=element('div',undefined,'body');body.append(element('p',item.kind==='default'?'Reference default':item.kind==='context'?item.mode+' · context winner':item.mode+' · round '+(item.round+1)+' · rank '+item.rank,'label'),element('h2',item.name));
if(item.variantImages){const label=element('label','Specimen');const select=element('select');['Neutral source default','With type · default','Variation 1','Variation 2','Variation 3'].forEach((text,i)=>{const option=element('option',text);option.value=i;select.append(option);});select.addEventListener('change',()=>{const i=Number(select.value);img.src=item.variantImages[i];preset.href=i===0?item.preset:'specimens/'+item.recipe+'/v'+(i-1)+'/preset.json';genome.href=i===0?item.genome:'specimens/'+item.recipe+'/v'+(i-1)+'/genome.json';if(pdf)pdf.href=i===0?item.pdf:'specimens/'+item.recipe+'/v'+(i-1)+'/poster.pdf';});label.append(select);body.append(label);}
const details=element('details');details.append(element('summary','System and source'),element('p',item.logic),link('Open complete reference poster',item.reference));body.append(details);const links=element('p',undefined,'links'),preset=link('Preset',item.preset),genome=link('Editable genome',item.genome),pdf=item.pdf?link('PDF',item.pdf):null;links.append(preset,genome);if(pdf)links.append(pdf);if(item.record)links.append(link('Round scores',item.record));body.append(links,element('p',item.tags.join(' · '),'tags'));card.append(figure,body);grid.append(card);}}
for(const control of [view,recipe])control.addEventListener('change',render);search.addEventListener('input',render);render();
</script></html>'''
(out/'gallery.html').write_text(page)
print('Gallery:',len(data),'specimens/candidate entries')
